function ScreenshotGallery() {
  const [active, setActive] = useState(0);
  const [lightbox, setLightbox] = useState(null);

  return (
    <div className="space-y-6">
      {/* Tab selectors */}
      <div className="flex flex-wrap gap-2">
        {screenshots.map((s, i) => (
          <button
            key={s.id}
            onClick={() => setActive(i)}
            className={`rounded-full border px-4 py-2 text-xs font-medium transition-all duration-200 ${
              active === i
                ? "border-cyan-400/40 bg-cyan-400/10 text-cyan-300"
                : "border-white/10 bg-white/[0.03] text-white/50 hover:border-white/20 hover:text-white/70"
            }`}
          >
            {s.label}
          </button>
        ))}
      </div>

      {/* Active screenshot */}
      <AnimatePresence mode="wait">
        <motion.div
          key={active}
          initial={{ opacity: 0, y: 12 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -12 }}
          transition={{ duration: 0.3 }}
          className="group relative"
        >
          <div className="overflow-hidden rounded-2xl border border-white/10 bg-black/40 shadow-2xl shadow-black/60 backdrop-blur-xl">
            {/* Window chrome */}
            <div className="flex items-center justify-between border-b border-white/[0.07] bg-[#0d1017]/80 px-4 py-2.5">
              <div className="flex items-center gap-2">
                <span className="h-3 w-3 rounded-full bg-[#ff5f57]" />
                <span className="h-3 w-3 rounded-full bg-[#febc2e]" />
                <span className="h-3 w-3 rounded-full bg-[#28c840]" />
              </div>
              <div className="text-[10px] font-medium uppercase tracking-[0.3em] text-white/30">Atlas · {screenshots[active].tag}</div>
              <div className="text-[10px] text-white/20">⌘K</div>
            </div>
            <div className="relative cursor-zoom-in" onClick={() => setLightbox(active)}>
              <img
                src={screenshots[active].img}
                alt={screenshots[active].label}
                className="w-full object-cover object-top"
                style={{maxHeight: '520px'}}
              />
              <div className="absolute inset-0 bg-gradient-to-t from-black/40 to-transparent opacity-0 transition-opacity duration-300 group-hover:opacity-100 flex items-center justify-center">
                <div className="rounded-full border border-white/20 bg-black/60 px-4 py-2 text-xs text-white backdrop-blur-xl">
                  Click to expand
                </div>
              </div>
            </div>
          </div>
          <p className="mt-4 text-sm leading-relaxed text-white/50">{screenshots[active].desc}</p>
        </motion.div>
      </AnimatePresence>

      {/* Lightbox */}
      <AnimatePresence>
        {lightbox !== null && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-[999] flex items-center justify-center bg-black/90 backdrop-blur-2xl p-4"
            onClick={() => setLightbox(null)}
          >
            <button
              onClick={() => setLightbox(null)}
              className="absolute right-6 top-6 rounded-full border border-white/20 bg-white/10 p-2 text-white hover:bg-white/20"
            >
              <X className="h-5 w-5" />
            </button>
            <motion.img
              initial={{ scale: 0.9 }}
              animate={{ scale: 1 }}
              exit={{ scale: 0.9 }}
              src={screenshots[lightbox].img}
              alt={screenshots[lightbox].label}
              className="max-h-[90vh] max-w-[95vw] rounded-xl border border-white/10 object-contain shadow-2xl"
              onClick={e => e.stopPropagation()}
            />
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

